import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-biochemistry-bioenergetics-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`How many ATP are produced per glucose in aerobic respiration?`]: {
    question: r`One glucose sends two acetyl-CoA through the Krebs cycle, which makes 6 NADH and 2 FADH₂ there. At about 2.5 ATP per NADH and 1.5 ATP per FADH₂, how many ATP does oxidative phosphorylation make from these Krebs cycle carriers alone?`,
    options: [r`About 22 ATP`, r`About 9 ATP`, r`About 20 ATP`, r`About 18 ATP`],
    correctAnswer: 3,
    explanation: r`6 NADH × 2.5 = 15 and 2 FADH₂ × 1.5 = 3, for 18 ATP. The answer 22 uses the outdated 3 and 2 ATP per carrier, 20 treats all eight carriers as NADH, and 9 counts only one turn of the cycle instead of the two turns per glucose.`,
  },
  [r`What is substrate-level phosphorylation?`]: {
    question: r`Which of these steps makes a nucleoside triphosphate by substrate-level phosphorylation?`,
    options: [r`ATP synthase forming ATP as protons flow back into the matrix`, r`Succinyl-CoA synthetase forming GTP as succinyl-CoA becomes succinate`, r`Hexokinase forming glucose 6-phosphate from glucose and ATP`, r`Malate dehydrogenase forming NADH as malate becomes oxaloacetate`],
    correctAnswer: 1,
    explanation: r`Succinyl-CoA synthetase uses the energy of a high-energy substrate, the thioester of succinyl-CoA, to phosphorylate GDP directly with no proton gradient involved. ATP synthase is oxidative phosphorylation, hexokinase consumes ATP rather than making it, and malate dehydrogenase makes a reduced carrier, not a triphosphate.`,
  },
  [r`What is the difference between $\Delta G$ and $\Delta G^\circ$?`]: {
    question: r`The same enzyme-catalyzed reaction, with ΔG°′ = −4 kJ/mol, is studied in two tissues. In liver it runs forward; in muscle, at the same temperature, it runs in reverse. Which statement explains this?`,
    options: [r`ΔG°′ and ΔG both change sign, because the standard state is redefined for each tissue`, r`ΔG°′ and ΔG are the same in both tissues, but each enzyme catalyzes only one direction`, r`ΔG°′ is the same in both tissues, but the actual ΔG changes sign with the concentrations`, r`ΔG is the same in both tissues, but the standard ΔG°′ changes sign with the concentrations`],
    correctAnswer: 2,
    explanation: r`ΔG°′ is a fixed property of the reaction at standard concentrations, while the actual ΔG depends on the real concentrations of reactants and products, which can differ enough between tissues to reverse its sign. The second answer swaps the roles of the two quantities, enzymes speed both directions and never set the direction, and the standard state is a fixed reference that does not change from tissue to tissue.`,
  },
  [r`The electron transport chain generates a proton gradient across the:`]: {
    question: r`A compound makes only the OUTER mitochondrial membrane freely permeable to protons and leaves the inner membrane intact. What happens to ATP synthesis driven by the electron transport chain?`,
    options: [r`It barely changes, because the proton gradient lies across the inner membrane`, r`It stops, because the pumped protons can no longer be held near ATP synthase`, r`It doubles, because cytosolic protons can now reach ATP synthase more easily`, r`It stops, because the proton gradient lies across the outer membrane instead`],
    correctAnswer: 0,
    explanation: r`The chain pumps protons across the inner mitochondrial membrane, and that membrane is the barrier that holds the gradient; the outer membrane is already leaky to small ions. The answers saying synthesis stops place the gradient across the outer membrane or assume the outer membrane traps the protons, and the answer saying it doubles ignores that the driving force is the difference across the inner membrane.`,
  },
  [r`Oxidative phosphorylation produces approximately how many ATP per glucose?`]: {
    question: r`A cell obtains about 32 ATP from one glucose. Glycolysis nets 2 ATP and the Krebs cycle makes 2 GTP, both by substrate-level phosphorylation. About how many of the 32 come from oxidative phosphorylation itself?`,
    options: [r`About 32 ATP`, r`About 28 ATP`, r`About 4 ATP`, r`About 30 ATP`],
    correctAnswer: 1,
    explanation: r`The 30 to 32 total includes 4 ATP equivalents made by substrate-level phosphorylation, so the electron transport chain and ATP synthase account for about 32 − 4 = 28. Answering 30 subtracts only the glycolytic ATP, 32 forgets that the total includes substrate-level ATP, and 4 is the substrate-level share itself.`,
  },
  [r`Which coenzyme is derived from vitamin B3 (niacin)?`]: {
    question: r`A patient's diet has been severely lacking in vitamin B3 (niacin) for months. Which enzyme most directly loses the supply of its coenzyme?`,
    options: [r`Transketolase, which uses thiamine pyrophosphate`, r`Malate dehydrogenase, which reduces NAD⁺ to NADH`, r`Pyruvate carboxylase, which uses biotin to add CO₂`, r`Succinate dehydrogenase, which reduces FAD to FADH₂`],
    correctAnswer: 1,
    explanation: r`Niacin is the precursor of NAD⁺, so NAD⁺-linked dehydrogenases such as malate dehydrogenase are hit directly. FAD comes from riboflavin (B2), biotin is its own vitamin, and thiamine pyrophosphate comes from thiamine (B1), so the other three enzymes depend on different vitamins.`,
  },
  [r`ATP synthase generates ATP by using energy from:`]: {
    question: r`Sealed vesicles made from inner mitochondrial membrane contain ATP synthase but no electron donors and no oxygen. An artificial pH difference is imposed across the membrane and ADP and phosphate are supplied. What is observed?`,
    options: [r`ATP is made, because a proton gradient alone can drive ATP synthase`, r`No ATP is made, because electrons must flow to oxygen at the same time`, r`ATP is made, because ADP and phosphate join spontaneously at low pH`, r`No ATP is made, because NADH must bind ATP synthase to power the enzyme`],
    correctAnswer: 0,
    explanation: r`ATP synthase is powered by protons flowing down their electrochemical gradient, so any gradient across the membrane, even an artificial one, drives synthesis. Electron transport only builds the gradient and is not needed once a gradient exists, NADH never touches the synthase, and ADP and phosphate do not join spontaneously because that reaction is strongly endergonic.`,
  },
  [r`The citric acid cycle occurs in which cellular compartment?`]: {
    question: r`A cell homogenate is separated into fractions. Which fraction contains nearly all of the isocitrate dehydrogenase and malate dehydrogenase activity belonging to the citric acid cycle?`,
    options: [r`Cytosol (soluble, outside organelles)`, r`Mitochondrial matrix (soluble interior)`, r`Inner mitochondrial membrane (bound)`, r`Intermembrane space (soluble layer)`],
    correctAnswer: 1,
    explanation: r`The citric acid cycle runs in the mitochondrial matrix, where its soluble enzymes are found. The inner membrane holds the electron transport chain, the intermembrane space receives pumped protons, and the cytosol is where glycolysis occurs, not the cycle.`,
  },
  [r`One glucose yields a NET of {{c1::2}} ATP and {{c2::2}} NADH in glycolysis.`]: {
    question: r`A yeast culture converts 5 molecules of glucose to pyruvate by glycolysis. What is the net yield of ATP and NADH from glycolysis itself?`,
    options: [r`A net of 10 ATP and 10 NADH`, r`A net of 20 ATP and 10 NADH`, r`A net of 5 ATP and 10 NADH`, r`A net of 10 ATP and 20 NADH`],
    correctAnswer: 0,
    explanation: r`Each glucose nets 2 ATP (4 made minus 2 invested) and 2 NADH, so 5 glucose give 10 ATP and 10 NADH. Answering 20 ATP counts the gross ATP and ignores the investment phase, 20 NADH doubles the NADH per glucose, and 5 ATP assumes only one net ATP per glucose.`,
  },
  [r`Protons are pumped into which compartment?`]: {
    question: r`A pH-sensitive dye is targeted to each mitochondrial compartment. When succinate and oxygen are supplied and the electron transport chain starts running, where do the pumped protons collect, and what does the dye report there?`,
    options: [r`In the mitochondrial matrix, where the pH falls`, r`In the mitochondrial matrix, where the pH rises`, r`In the intermembrane space, where the pH rises`, r`In the intermembrane space, where the pH falls`],
    correctAnswer: 3,
    explanation: r`The complexes pump protons out of the matrix into the intermembrane space, so that compartment gains H⁺ and its pH falls. A rising pH there reverses the meaning of pH, and both matrix answers put the pumped protons on the side they were removed from (the matrix loses protons, so its pH rises, but the protons do not collect there).`,
  },
  [r`Which reaction is the committed step of the citric acid cycle?`]: {
    question: r`An inhibitor blocks the enzyme that commits acetyl groups to the citric acid cycle by condensing them with the four-carbon acceptor. Which enzyme is this, and what builds up right away?`,
    options: [r`Isocitrate dehydrogenase; acetyl-CoA and oxaloacetate build up`, r`Citrate synthase; citrate and isocitrate build up`, r`Isocitrate dehydrogenase; citrate and isocitrate build up`, r`Citrate synthase; acetyl-CoA and oxaloacetate build up`],
    correctAnswer: 3,
    explanation: r`The committed entry step is citrate synthase, which joins acetyl-CoA to oxaloacetate, so blocking it makes those two substrates accumulate while citrate falls. Isocitrate dehydrogenase is the main rate-limiting regulatory point, not the condensation step, and citrate and isocitrate would build up only if a step after citrate formation were blocked.`,
  },
  [r`The energy charge of a cell is defined using:`]: {
    question: r`Cell A contains 5 mM ATP, 0.5 mM ADP and 0.05 mM AMP. Cell B contains 2.5 mM ATP, 2 mM ADP and 1 mM AMP. Which cell has the higher energy charge, and how is glycolysis regulated in that cell compared with the other?`,
    options: [r`Cell A has the higher charge, and its glycolysis is stimulated`, r`Cell A has the higher charge, and its glycolysis is restrained`, r`Cell B has the higher charge, and its glycolysis is restrained`, r`Cell B has the higher charge, and its glycolysis is stimulated`],
    correctAnswer: 1,
    explanation: r`Energy charge reflects how much of the adenylate pool is ATP rather than ADP and AMP, so Cell A, which is almost all ATP, has the higher charge, and a high charge inhibits ATP-producing catabolic pathways such as glycolysis. Choosing Cell B mistakes abundant ADP and AMP for stored energy, and saying glycolysis is stimulated at high charge reverses the feedback.`,
  },
  [r`Approximately how many ATP result from complete oxidation of one glucose?`]: {
    question: r`Older textbooks credited one glucose with 36 to 38 ATP, using 3 ATP per NADH and 2 per FADH₂. Which fact best explains why the accepted figure is now about 30 to 32?`,
    options: [r`The Krebs cycle is now known to make only four NADH per glucose, so fewer carriers are formed`, r`Oxygen is now known to accept only one electron per NADH, so half of the carriers are wasted`, r`Importing phosphate and exchanging ADP for ATP costs protons, so each NADH gives about 2.5 ATP`, r`Glycolysis is now known to net only one ATP per glucose, so two ATP are dropped from the total`],
    correctAnswer: 2,
    explanation: r`The modern estimate counts transport costs: protons are spent bringing phosphate in and swapping ATP for ADP, so about 4 protons are needed per ATP and NADH yields about 2.5 rather than 3. The other answers change the carrier counts or the chemistry, but glycolysis still nets 2 ATP, the cycle still makes 6 NADH per glucose, and each NADH still passes two electrons to oxygen.`,
  },
  [r`NADH delivers electrons to which complex?`]: {
    question: r`A patient inherits a defect that leaves Complex I nonfunctional, while the rest of the electron transport chain is normal. Which finding is expected in the patient's mitochondria?`,
    options: [r`Nothing builds up, because NADH passes its electrons to Complex II`, r`FADH₂ builds up, while NADH can still pass electrons to the chain`, r`NADH builds up, while succinate can still pass electrons to the chain`, r`NADH builds up, and succinate can no longer pass electrons to the chain`],
    correctAnswer: 2,
    explanation: r`NADH delivers its electrons only to Complex I, so without it NADH accumulates; succinate-derived FADH₂ enters at Complex II and is unaffected. Saying succinate oxidation also stops ignores that Complex II bypasses Complex I, the FADH₂ answer swaps the two entry points, and NADH cannot use Complex II as an alternative entry.`,
  },
  [r`Which metabolic state has the highest ATP demand?`]: {
    question: r`The ATP turnover of one person's leg muscle is measured in four states. Which state shows the highest ATP demand, and which sources meet that demand first?`,
    options: [r`Digesting a big meal, met first by anaerobic glycolysis and then ketone bodies`, r`Overnight fasting, met first by creatine phosphate and then anaerobic glycolysis`, r`Maximal sprinting, met first by fatty acid oxidation and then creatine phosphate`, r`Maximal sprinting, met first by creatine phosphate and then anaerobic glycolysis`],
    correctAnswer: 3,
    explanation: r`Intense exercise raises muscle ATP demand far above any resting state, and muscle covers the first seconds with creatine phosphate and then anaerobic glycolysis. Fatty acid oxidation is too slow to lead a sprint, and fasting and the fed state are low-demand resting states for muscle.`,
  },
  [r`ATP hydrolysis has $\Delta G^{\circ\prime} \approx -30.5$ kJ/mol, yet cellular $\Delta G$ is about $-50$ kJ/mol. Why the difference?`]: {
    question: r`In a healthy cell the ΔG of ATP hydrolysis is about −50 kJ/mol. A poison lets the ATP/ADP ratio fall 100-fold while phosphate is unchanged. Taking RT ≈ 2.5 kJ/mol and ln 100 ≈ 4.6, what is the new ΔG of ATP hydrolysis?`,
    options: [r`About −30.5 kJ/mol`, r`About −61.5 kJ/mol`, r`About −38.5 kJ/mol`, r`About −50.0 kJ/mol`],
    correctAnswer: 2,
    explanation: r`Hydrolysis has Q = [ADP][Pᵢ]/[ATP], so a 100-fold fall in ATP/ADP raises Q 100-fold and adds RT ln 100 = +11.5 kJ/mol, giving −50 + 11.5 = −38.5 kJ/mol. The value −61.5 applies the shift with the wrong sign, −50 assumes ΔG does not depend on concentrations, and −30.5 is the standard value, which is reached only when Q = 1.`,
  },
  [r`Vitamin precursors: NAD$^+$ derives from {{c1::niacin (B3)}} and FAD from {{c2::riboflavin (B2)}}.`]: {
    question: r`Cells are grown with radiolabeled riboflavin in one flask and radiolabeled niacin in another. Which electron-carrying coenzymes become labeled?`,
    options: [r`Riboflavin labels TPP; niacin labels NAD⁺`, r`Riboflavin labels NAD⁺; niacin labels FAD`, r`Riboflavin labels FAD; niacin labels NAD⁺`, r`Riboflavin labels FAD; niacin labels CoA`],
    correctAnswer: 2,
    explanation: r`FAD is built from riboflavin (B2) and NAD⁺ from niacin (B3). The swapped answer reverses the two pairings, coenzyme A comes from pantothenic acid (B5), and thiamine pyrophosphate (TPP) comes from thiamine (B1).`,
  },
  [r`Biochemical standard state for $\Delta G^{\circ\prime}$: pH {{c1::7}}, 1 M solutes, 25 C.`]: {
    question: r`A reaction releases one H⁺ as a product. Its free-energy change is tabulated twice: under the chemical standard state (1 M H⁺) and under the biochemical standard state marked with a prime. How does the primed value compare?`,
    options: [r`More negative, because H⁺ is fixed at 10⁻⁷ M (pH 7)`, r`More negative, because H⁺ is fixed at 10⁻¹ M (pH 1)`, r`The same, because H⁺ is fixed at 1 M in both states`, r`More positive, because H⁺ is fixed at 10⁻⁷ M (pH 7)`],
    correctAnswer: 0,
    explanation: r`The prime means pH 7, so the product H⁺ is held at 10⁻⁷ M instead of 1 M, and a much lower product concentration makes the reaction more favorable. Calling it more positive reverses the effect of lowering a product, pH 1 is not the biochemical convention, and the two standard states differ precisely in their H⁺ concentration.`,
  },
  [r`Why must PEP and 1,3-BPG have higher phosphoryl-transfer potential than ATP?`]: {
    question: r`A newly found metabolite X-phosphate has a hydrolysis ΔG°′ of −20 kJ/mol. ATP hydrolysis has ΔG°′ = −30.5 kJ/mol. Under standard conditions, can X-phosphate phosphorylate ADP in a substrate-level phosphorylation?`,
    options: [r`No: the transfer to ADP would have ΔG°′ ≈ +10.5 kJ/mol`, r`Yes: the transfer to ADP would have ΔG°′ ≈ −50.5 kJ/mol`, r`No: the transfer to ADP would have ΔG°′ ≈ +50.5 kJ/mol`, r`Yes: the transfer to ADP would have ΔG°′ ≈ −10.5 kJ/mol`],
    correctAnswer: 0,
    explanation: r`Transfer to ADP is hydrolysis of the donor (−20) plus synthesis of ATP (+30.5), giving +10.5 kJ/mol, so it is uphill. A donor must sit above ATP in phosphoryl-transfer potential, as PEP and 1,3-BPG do. The −10.5 answer subtracts in the wrong order, and the ±50.5 answers add the two hydrolysis values instead of reversing the ATP term.`,
  },
  [r`In the first seconds of intense exercise, muscle regenerates ATP from {{c1::creatine phosphate}} via creatine kinase.`]: {
    question: r`A muscle biopsy is taken 5 seconds into an all-out sprint. ATP concentration is almost unchanged. Which fuel store has fallen the most, and why?`,
    options: [r`Blood glucose, which oxidative phosphorylation uses to rephosphorylate ADP`, r`Stored triacylglycerol, which beta-oxidation uses to rephosphorylate ADP`, r`Creatine phosphate, which creatine kinase uses to rephosphorylate ADP`, r`Muscle glycogen, which anaerobic glycolysis uses to rephosphorylate ADP`],
    correctAnswer: 2,
    explanation: r`In the first seconds, creatine kinase transfers the phosphate of creatine phosphate to ADP almost instantly, holding ATP steady while that store drains. Glycolysis takes several seconds to ramp up, and fat oxidation and oxidative phosphorylation of blood glucose are much slower still.`,
  },
  [r`Complex III (cytochrome $bc_1$) moves electrons from CoQ to cytochrome c via the {{c1::Q cycle}} and is blocked by {{c2::antimycin A}}.`]: {
    question: r`Reduced CoQ arrives at one complex carrying two electrons, but the acceptor there, cytochrome c, can take only one at a time. Which mechanism handles this mismatch, and which inhibitor blocks it?`,
    options: [r`The Q cycle of Complex IV, which antimycin A blocks`, r`The Q cycle of Complex III, which antimycin A blocks`, r`The Q cycle of Complex III, which rotenone blocks`, r`The Q cycle of Complex IV, which cyanide blocks`],
    correctAnswer: 1,
    explanation: r`Complex III (cytochrome bc₁) uses the Q cycle to pass the two electrons of reduced CoQ one at a time to cytochrome c, and antimycin A inhibits it. Rotenone blocks Complex I, and Complex IV receives electrons from cytochrome c rather than from CoQ, with cyanide as its inhibitor.`,
  },
  [r`Predict the effects of a DNP overdose on $O_2$ consumption, ATP levels, and body temperature.`]: {
    question: r`Compound X is a lipid-soluble weak acid that picks up H⁺ in the intermembrane space and releases it in the matrix. Predict what a large dose does to a patient's O₂ consumption, ATP synthesis and body temperature.`,
    options: [r`O₂ use falls, ATP synthesis falls, temperature falls`, r`O₂ use falls, ATP synthesis falls, temperature rises`, r`O₂ use rises, ATP synthesis falls, temperature rises`, r`O₂ use rises, ATP synthesis rises, temperature rises`],
    correctAnswer: 2,
    explanation: r`Compound X is an uncoupler like dinitrophenol: with the gradient leaking away, electron transport and O₂ use speed up, ATP synthase is bypassed so ATP output falls, and the energy appears as heat. Falling O₂ use describes an electron transport inhibitor, and rising ATP synthesis ignores that the protons no longer pass through the synthase.`,
  },
  [r`Why do cytosolic NADH electrons need a shuttle system at all?`]: {
    question: r`NADH carrying a radioactive label in its nicotinamide ring is made in the cytosol of a liver cell. After its electrons have been passed to the electron transport chain, where is the radioactive label found?`,
    options: [r`In matrix NADH, because NADH crosses on a dedicated carrier protein`, r`In matrix NAD⁺, because NADH crosses and is oxidized at Complex I`, r`In cytosolic NAD⁺, because only the electrons cross the inner membrane`, r`In cytosolic NADH, because its electrons cannot reach the chain at all`],
    correctAnswer: 2,
    explanation: r`The inner mitochondrial membrane is impermeable to NADH and NAD⁺, so a shuttle carries only the electrons across on metabolites such as malate, leaving the labeled coenzyme in the cytosol as NAD⁺. The matrix answers assume the coenzyme itself crosses, and the last answer ignores the shuttles that regenerate cytosolic NAD⁺.`,
  },
  [r`How does cytochrome c differ from CoQ as an electron carrier?`]: {
    question: r`Mitochondria whose outer membrane has been removed are washed gently with a salt solution and no detergent. One electron carrier washes away and respiration stops. Which carrier is lost, and why?`,
    options: [r`Coenzyme Q, a lipid-soluble molecule dissolved inside the membrane bilayer`, r`Cytochrome c, a water-soluble protein loosely bound to the membrane surface`, r`Coenzyme Q, a water-soluble protein loosely bound to the membrane surface`, r`Cytochrome c, a lipid-soluble molecule dissolved inside the membrane bilayer`],
    correctAnswer: 1,
    explanation: r`Cytochrome c is a small water-soluble protein held loosely on the outer face of the inner membrane, so salt alone removes it. Coenzyme Q is a lipid-soluble quinone inside the bilayer and would need detergent or organic solvent to extract; the two mixed answers attach each carrier to the other's description.`,
  },
  [r`Which ETC complexes pump protons, and how many total per matrix NADH?`]: {
    question: r`Mitochondria oxidize 2 NADH (made in the matrix) and 2 succinate. In total, how many protons are pumped across the inner membrane as these four electron pairs travel to oxygen?`,
    options: [r`24 protons`, r`28 protons`, r`40 protons`, r`32 protons`],
    correctAnswer: 3,
    explanation: r`Each NADH pair passes Complexes I, III and IV (4 + 4 + 2 = 10 protons); each succinate pair enters at Complex II, which pumps none, and passes only III and IV (6 protons). The total is 2 × 10 + 2 × 6 = 32. Forty treats succinate like NADH, 24 treats NADH like succinate, and 28 credits succinate with only 4 protons per pair.`,
  },
  [r`In the binding-change mechanism, what step actually consumes most of the proton-motive energy?`]: {
    question: r`Isolated F₁ heads of ATP synthase, with no proton gradient, are given ADP and phosphate. ATP forms on the enzyme but stays stuck in the catalytic site. What does this show about where the energy of the proton gradient is mainly spent?`,
    options: [r`On forming the phosphoanhydride bond of the bound ATP`, r`On releasing tightly bound ATP from the catalytic site`, r`On pumping protons outward through the F₀ channel`, r`On binding ADP and phosphate at the open catalytic site`],
    correctAnswer: 1,
    explanation: r`In the binding-change mechanism, ATP forms almost without energy cost in the tight site; proton-driven rotation of the gamma subunit is needed to open the site and release it. The bond-formation answer is the common trap, substrate binding does not need the gradient, and the synthase lets protons flow inward rather than pumping them out.`,
  },
  [r`Why does complete glucose oxidation yield about 30 ATP in some tissues and about 32 in others?`]: {
    question: r`Heart cells use the malate-aspartate shuttle and a certain skeletal muscle uses only the glycerol 3-phosphate shuttle. With 2.5 ATP per NADH and 1.5 ATP per FADH₂, how many more ATP does the heart cell obtain from the complete oxidation of 5 glucose molecules?`,
    options: [r`15 more ATP`, r`25 more ATP`, r`5 more ATP`, r`10 more ATP`],
    correctAnswer: 3,
    explanation: r`The only difference is the 2 cytosolic NADH from glycolysis: worth 2.5 ATP each by the malate-aspartate shuttle and 1.5 each by the glycerol 3-phosphate shuttle, a gap of 2 ATP per glucose and 10 for 5 glucose. Five counts one NADH per glucose, while 15 and 25 give the whole value of the shuttled carriers instead of the difference.`,
  },
  [r`The ATP-ADP translocase antiports matrix {{c1::ATP}} outward for cytosolic {{c2::ADP}} inward, driven partly by the membrane potential.`]: {
    question: r`During respiration the matrix side of the inner membrane is electrically negative relative to the outside. Which exchange by the ATP-ADP translocase does this membrane potential help drive?`,
    options: [r`ADP³⁻ out and ATP⁴⁻ in, a net positive charge moving in`, r`ATP⁴⁻ out and ADP³⁻ in, a net positive charge moving out`, r`ADP³⁻ out and ATP⁴⁻ in, a net negative charge moving in`, r`ATP⁴⁻ out and ADP³⁻ in, a net negative charge moving out`],
    correctAnswer: 3,
    explanation: r`The translocase exports matrix ATP⁴⁻ in exchange for cytosolic ADP³⁻, which moves one net negative charge out of the negative matrix toward the positive outside, so the potential favors it. The answers that send ATP inward reverse the direction the cell needs, and the answers with a net positive charge miscount the charges on the two nucleotides.`,
  },
  [r`Respiratory quotient ($RQ = CO_2$ produced $/ O_2$ consumed): carbohydrate {{c1::1.0}}, fat {{c2::~0.7}}, protein ~0.8.`]: {
    question: r`Indirect calorimetry on a resting patient gives 210 mL of CO₂ produced and 300 mL of O₂ consumed per minute. Which fuel is the patient mainly oxidizing?`,
    options: [r`Fat, because the respiratory quotient is about 1.4`, r`Carbohydrate, because the respiratory quotient is about 1.4`, r`Fat, because the respiratory quotient is about 0.7`, r`Carbohydrate, because the respiratory quotient is about 0.7`],
    correctAnswer: 2,
    explanation: r`RQ = CO₂ produced / O₂ consumed = 210/300 = 0.70, the value for fat oxidation; carbohydrate gives 1.0. The answers with 1.4 invert the ratio to O₂ over CO₂, and pairing 0.7 with carbohydrate mixes up the two fuel values.`,
  },
  [r`How does energetic coupling allow glutamine synthesis (unfavorable) to proceed?`]: {
    question: r`Forming glutamine from glutamate and ammonia has ΔG°′ of about +14 kJ/mol, and ATP hydrolysis has ΔG°′ = −30.5 kJ/mol. A student mixes glutamate, ammonia, ATP and an unrelated ATPase that simply hydrolyzes ATP. Is glutamine formation now driven forward?`,
    options: [r`Yes, because the phosphate freed from ATP shifts the amidation equilibrium forward`, r`No, because coupling requires a shared intermediate such as γ-glutamyl phosphate`, r`Yes, because any exergonic reaction in the same solution lowers the other's ΔG`, r`No, because the two ΔG°′ values still add up to a positive number when combined`],
    correctAnswer: 1,
    explanation: r`Energetic coupling works only when the two reactions share an intermediate; glutamine synthetase makes γ-glutamyl phosphate, so the free-energy changes add. A separate ATPase just releases the energy as heat. The sum, +14 − 30.5 = −16.5 kJ/mol, is negative, so the arithmetic answer is wrong, and neither nearby exergonic reactions nor free phosphate change the amidation equilibrium.`,
  },
  [r`Why is the respiratory quotient lower for fat than for carbohydrate?`]: {
    question: r`Oxidizing one glucose uses 6 O₂ and releases 6 CO₂. Oxidizing one palmitate, a 16-carbon saturated fatty acid, uses 23 O₂ and releases 16 CO₂. What explains the difference in these ratios?`,
    options: [r`Fat carbons are more oxidized, so more O₂ is needed per CO₂ released`, r`Fat carbons are more oxidized, so less O₂ is needed per CO₂ released`, r`Fat carbons are more reduced, so more O₂ is needed per CO₂ released`, r`Fat carbons are more reduced, so less O₂ is needed per CO₂ released`],
    correctAnswer: 2,
    explanation: r`Fatty acid carbons are mostly CH₂ groups with almost no oxygen, so extra O₂ is consumed oxidizing all that hydrogen to water, giving 16/23 ≈ 0.7 against 6/6 = 1.0 for glucose. Carbohydrate carbons, not fat carbons, are the partly oxidized ones, and the data show more O₂ per CO₂ for fat, not less.`,
  },
  [r`Standard reduction potentials: NAD$^+$/NADH $=$ {{c1::$-0.32$ V}}; $O_2$/H$_2$O $=$ {{c2::$+0.82$ V}}.`]: {
    question: r`The standard reduction potential of NAD⁺/NADH is −0.32 V and that of oxidized/reduced coenzyme Q is about +0.05 V. What is ΔE°′ for electron transfer from NADH to coenzyme Q?`,
    options: [r`−0.27 V`, r`+0.27 V`, r`+0.37 V`, r`−0.37 V`],
    correctAnswer: 2,
    explanation: r`ΔE°′ is the acceptor potential minus the donor potential: +0.05 − (−0.32) = +0.37 V, a positive value that matches the spontaneous direction of flow. The value −0.37 V subtracts in the wrong order, and ±0.27 V drops the negative sign on the NAD⁺/NADH potential.`,
  },
  [r`Why does releasing pyrophosphate (PP$_i$) make reactions like fatty acyl-CoA and aminoacyl-tRNA formation effectively irreversible?`]: {
    question: r`Activating a fatty acid (fatty acid + CoA + ATP → fatty acyl-CoA + AMP + PPᵢ) has a ΔG°′ near zero. In a cell whose inorganic pyrophosphatase is inhibited, what happens?`,
    options: [r`PPᵢ builds up, and activation stalls near equilibrium instead of being pulled forward`, r`PPᵢ runs out, and activation stalls because AMP can no longer leave the enzyme`, r`PPᵢ runs out, and activation speeds up because ATP is regenerated from the AMP`, r`PPᵢ builds up, and activation speeds up because the extra product drives it forward`],
    correctAnswer: 0,
    explanation: r`Pyrophosphatase normally hydrolyzes PPᵢ at once, removing a product and making the activation effectively irreversible; without it PPᵢ accumulates and the near-zero ΔG°′ reaction settles near equilibrium. Product buildup opposes a reaction rather than driving it, and inhibiting the enzyme that destroys PPᵢ cannot make PPᵢ run out.`,
  },
  [r`What is thermogenin (UCP1), and where does it function?`]: {
    question: r`Mitochondria from the brown fat of a cold-exposed newborn consume O₂ quickly yet make little ATP, although no drug is present. Which protein explains this, and where does it act?`,
    options: [r`Cytochrome c, a proton pump in the inner mitochondrial membrane`, r`ATP synthase, a proton channel in the outer mitochondrial membrane`, r`Thermogenin, a proton channel in the inner mitochondrial membrane`, r`Thermogenin, a proton pump in the outer mitochondrial membrane`],
    correctAnswer: 2,
    explanation: r`Thermogenin (UCP1) is a regulated proton channel in the inner membrane of brown fat mitochondria; it lets protons return to the matrix without passing through ATP synthase, so the energy is released as heat. It is a channel in the inner membrane, not a pump in the outer one, ATP synthase sits in the inner membrane and makes ATP, and cytochrome c carries electrons, not protons.`,
  },
  [r`NAD$^+$ accepts a {{c1::hydride (two electrons plus one proton)}}; FAD accepts {{c2::two electrons and two protons}}.`]: {
    question: r`Lactate dehydrogenase removes two hydrogen atoms (two electrons and two protons in all) from lactate and uses NAD⁺ as the acceptor. Where do they go?`,
    options: [r`Both hydrogens go to NAD⁺ to give NADH₂, and no H⁺ enters the solution`, r`A hydride goes to NAD⁺ to give NADH, and one H⁺ enters the solution`, r`One electron goes to NAD⁺ to give NADH, and a hydride enters the solution`, r`Two electrons go to NAD⁺ to give NADH, and two H⁺ enter the solution`],
    correctAnswer: 1,
    explanation: r`NAD⁺ accepts a hydride, which is two electrons plus one proton, becoming NADH, and the second proton is released to the solvent. Taking both hydrogens describes FAD becoming FADH₂, NAD⁺ does not accept single electrons, and if both protons went to solution the product would not be NADH.`,
  },
  [r`Consensus P/O yields: matrix NADH makes about {{c1::2.5}} ATP; FADH$_2$ makes about {{c2::1.5}} ATP.`]: {
    question: r`A degradation pathway hands the mitochondrial matrix 3 NADH and 2 FADH₂. Using the consensus yields per carrier, about how many ATP does oxidative phosphorylation make from them?`,
    options: [r`About 12.5 ATP`, r`About 9.5 ATP`, r`About 10.5 ATP`, r`About 13.0 ATP`],
    correctAnswer: 2,
    explanation: r`3 NADH × 2.5 = 7.5 and 2 FADH₂ × 1.5 = 3, for 10.5 ATP. Thirteen uses the outdated 3 and 2 per carrier, 9.5 swaps the two yields (3 × 1.5 + 2 × 2.5), and 12.5 gives all five carriers the NADH value.`,
  },
  [r`Complex I (NADH dehydrogenase) pumps {{c1::4}} H$^+$ per NADH and is inhibited by {{c2::rotenone}}.`]: {
    question: r`Rotenone is added to mitochondria that are oxidizing glutamate, an NADH-linked substrate. Which electron transfer is blocked directly, and how many protons does that step normally pump per NADH?`,
    options: [r`CoQ to cytochrome c, a step that normally pumps 4 H⁺`, r`NADH to CoQ, a step that normally pumps 4 H⁺`, r`Succinate to CoQ, a step that normally pumps 4 H⁺`, r`NADH to CoQ, a step that normally pumps 2 H⁺`],
    correctAnswer: 1,
    explanation: r`Rotenone inhibits Complex I, which passes electrons from NADH to CoQ and pumps 4 protons per NADH. Two protons is the count for Complex IV, succinate to CoQ is Complex II and pumps none, and CoQ to cytochrome c is Complex III, whose inhibitor is antimycin A.`,
  },
  [r`Complex II ({{c1::succinate dehydrogenase}}) pumps {{c2::no}} protons and is the only ETC complex that is also a citric acid cycle enzyme.`]: {
    question: r`A mutation destroys one enzyme, and both the citric acid cycle and the electron transport chain lose a step. Which enzyme is it, and how many protons does it pump per electron pair?`,
    options: [r`Succinate dehydrogenase (Complex II), which pumps no protons`, r`Malate dehydrogenase (Complex I), which pumps 4 protons`, r`Succinate dehydrogenase (Complex II), which pumps 4 protons`, r`Malate dehydrogenase (Complex II), which pumps no protons`],
    correctAnswer: 0,
    explanation: r`Succinate dehydrogenase is the only citric acid cycle enzyme that is also a respiratory complex, Complex II, and it passes electrons to CoQ without pumping protons. Four protons is the count for Complex I or III, and malate dehydrogenase is a soluble matrix enzyme that is not part of any complex.`,
  },
  [r`Complex {{c1::IV}} (cytochrome c oxidase) reduces $O_2$ to water and is inhibited by {{c2::cyanide, carbon monoxide, and azide}}.`]: {
    question: r`Mitochondria supplied with succinate are poisoned. Oxygen is no longer consumed, and every carrier including cytochrome c is found fully reduced. Which complex is blocked, and by which kind of agent?`,
    options: [r`Complex IV, blocked by an agent such as cyanide`, r`Complex III, blocked by an agent such as antimycin A`, r`Complex III, blocked by an agent such as cyanide`, r`Complex I, blocked by an agent such as rotenone`],
    correctAnswer: 0,
    explanation: r`If cytochrome c is fully reduced, electrons reach it but cannot leave, so the block is at Complex IV (cytochrome c oxidase), which cyanide, carbon monoxide and azide inhibit. A Complex III block by antimycin A would leave cytochrome c oxidized, cyanide does not act at Complex III, and rotenone at Complex I would not stop succinate oxidation.`,
  },
  [r`Mitochondria are poisoned with rotenone. Can succinate still drive $O_2$ consumption? Can malate?`]: {
    question: r`A researcher wants to study electron flow through Complexes II, III and IV only, so she adds rotenone to the mitochondria. Which substrate must she supply to see O₂ consumption, and why?`,
    options: [r`Malate, because its NADH is oxidized at Complex III, past the block`, r`Succinate, because its electrons enter at Complex II, past the block`, r`Malate, because its electrons enter at Complex II, past the block`, r`Succinate, because its NADH is oxidized at Complex I despite the block`],
    correctAnswer: 1,
    explanation: r`Rotenone blocks Complex I, so only a substrate that feeds electrons in downstream will work: succinate is oxidized by Complex II, which reduces CoQ directly. Malate makes NADH, which must use Complex I and so cannot be oxidized, and succinate does not produce NADH at all.`,
  },
  [r`When an ETC inhibitor acts, carriers upstream of the block become more ___ and carriers downstream become more ___.`]: {
    question: r`Antimycin A, which blocks Complex III, is added to mitochondria that are oxidizing NADH. How do the redox states of the carriers change?`,
    options: [r`NADH and CoQ become more oxidized; cytochrome c and Complex IV more reduced`, r`NADH, CoQ, cytochrome c and Complex IV all become more oxidized than before`, r`NADH and CoQ become more reduced; cytochrome c and Complex IV more oxidized`, r`NADH, CoQ, cytochrome c and Complex IV all become more reduced than before`],
    correctAnswer: 2,
    explanation: r`Carriers upstream of a block fill with electrons and become reduced, while carriers downstream keep passing their electrons to oxygen and become oxidized. With the block at Complex III, NADH and CoQ are upstream and cytochrome c and Complex IV are downstream. The reversed answer flips this crossover, and the all-reduced pattern would need a block at the very end of the chain.`,
  },
  [r`ATP synthase: {{c1::$F_0$}} is the membrane proton channel (c-ring); {{c2::$F_1$}} holds the catalytic sites; {{c3::oligomycin}} inhibits it.`]: {
    question: r`The knob-like heads of ATP synthase are stripped from inner-membrane vesicles. The stripped membranes now leak protons freely, and adding oligomycin seals the leak. What does this show?`,
    options: [r`F₁ is the proton channel, and oligomycin acts on F₁`, r`F₁ is the proton channel, and oligomycin acts on F₀`, r`F₀ holds the catalytic sites, and oligomycin acts on F₁`, r`F₀ is the proton channel, and oligomycin acts on F₀`],
    correctAnswer: 3,
    explanation: r`The part left in the membrane after the heads are removed is F₀, so the leak shows F₀ is the proton channel, and sealing it with oligomycin shows oligomycin blocks F₀. The removed F₁ heads hold the catalytic sites and cannot be the leak, since they are no longer on the membrane.`,
  },
  [r`The proton-motive force has two components: a chemical gradient ({{c1::$\Delta$pH}}) and an electrical gradient ({{c2::membrane potential, $\Delta\psi$}}).`]: {
    question: r`An ionophore exchanges one H⁺ for one K⁺ across the inner mitochondrial membrane, so protons move down their gradient with no net movement of charge. Which part of the proton-motive force does it dissipate?`,
    options: [r`Only Δψ, because charge moves but no net protons move`, r`Both ΔpH and Δψ, because every proton carries a charge`, r`Only ΔpH, because protons move but no net charge moves`, r`Neither ΔpH nor Δψ, because the exchange is neutral`],
    correctAnswer: 2,
    explanation: r`The proton-motive force has a chemical part (ΔpH) and an electrical part (the membrane potential, Δψ). A one-for-one exchange of H⁺ for K⁺ lets protons equalize, collapsing ΔpH, while moving no net charge, leaving Δψ intact. Collapsing only Δψ needs charge movement without proton movement, and collapsing both needs protons to cross carrying their charge uncompensated.`,
  },
  [r`Uncouplers such as {{c1::2,4-dinitrophenol}} are lipid-soluble {{c2::protonophores}} that release the gradient's energy as {{c3::heat}}.`]: {
    question: r`Mitochondria treated with 2,4-dinitrophenol oxidize NADH faster than before, yet they make almost no ATP. Where does the free energy released by electron transport end up?`,
    options: [r`It is released as heat as protons leak back across the membrane`, r`It is captured as GTP by substrate-level phosphorylation`, r`It is stored in a larger proton gradient across the membrane`, r`It is stored in NADH that builds up inside the matrix`],
    correctAnswer: 0,
    explanation: r`Dinitrophenol is a lipid-soluble protonophore: it carries protons back across the inner membrane, bypassing ATP synthase, so the energy of the gradient is lost as heat. The gradient shrinks rather than grows, NADH is consumed faster rather than accumulating, and substrate-level phosphorylation does not capture energy from the gradient.`,
  },
  [r`$\Delta G^{\circ\prime} = -nF\Delta E^{\circ\prime}$: a redox reaction is spontaneous when $\Delta E^{\circ\prime}$ is {{c1::positive}}.`]: {
    question: r`The fumarate/succinate couple has E°′ = +0.03 V and the NAD⁺/NADH couple has E°′ = −0.32 V. Under standard conditions, could succinate reduce NAD⁺ spontaneously?`,
    options: [r`No: ΔE°′ = −0.35 V, so ΔG°′ is positive`, r`Yes: ΔE°′ = −0.35 V, so ΔG°′ is negative`, r`No: ΔE°′ = +0.35 V, so ΔG°′ is positive`, r`Yes: ΔE°′ = +0.35 V, so ΔG°′ is negative`],
    correctAnswer: 0,
    explanation: r`ΔE°′ = acceptor − donor = −0.32 − (+0.03) = −0.35 V, and with ΔG°′ = −nFΔE°′ a negative potential gives a positive free-energy change, so the transfer is not spontaneous (which is why succinate dehydrogenase uses FAD). The +0.35 V answers subtract in the wrong order, and the answers pairing a negative ΔE°′ with a negative ΔG°′, or a positive with a positive, drop the minus sign in the equation.`,
  },
  [r`Electrons in the ETC flow spontaneously toward carriers with more ___ reduction potential.`]: {
    question: r`Three unknown electron carriers are isolated with standard reduction potentials of +0.22 V, −0.10 V and +0.40 V. In what order do electrons pass through them spontaneously?`,
    options: [r`From +0.40 V to +0.22 V to −0.10 V`, r`From −0.10 V to +0.40 V to +0.22 V`, r`From +0.22 V to −0.10 V to +0.40 V`, r`From −0.10 V to +0.22 V to +0.40 V`],
    correctAnswer: 3,
    explanation: r`Electrons flow spontaneously toward carriers with a more positive reduction potential, meaning greater electron affinity, so the order runs from −0.10 V up to +0.40 V. The reversed order sends electrons toward lower affinity, and the other two orders each include one step to a less positive potential.`,
  },
  [r`$\Delta G^{\circ\prime} = -RT\ln K_{eq}$: a negative $\Delta G^{\circ\prime}$ means $K_{eq}$ {{c1::greater than 1}}; at equilibrium $\Delta G =$ {{c2::0}}.`]: {
    question: r`An isomerase is added to its substrate and the mixture is left until the concentrations stop changing under biochemical standard conditions. Product is then 20 times more concentrated than substrate. What is true of this final mixture?`,
    options: [r`ΔG°′ is zero, and the actual ΔG is also zero`, r`ΔG°′ is positive, and the actual ΔG is zero`, r`ΔG°′ is negative, and the actual ΔG is zero`, r`ΔG°′ is zero, and the actual ΔG is negative`],
    correctAnswer: 2,
    explanation: r`The mixture is at equilibrium with K_eq = 20, which is greater than 1, so ΔG°′ = −RT ln K_eq is negative, while the actual ΔG at equilibrium is always zero. A zero ΔG°′ would require K_eq = 1, and a positive ΔG°′ would require substrate to be favored at equilibrium.`,
  },
  [r`Some glycolytic steps (e.g., aldolase) have positive $\Delta G^{\circ\prime}$ yet run forward in cells. How?`]: {
    question: r`Triose phosphate isomerase converts dihydroxyacetone phosphate to glyceraldehyde 3-phosphate with ΔG°′ of about +7.5 kJ/mol, yet the reaction runs forward in glycolysis. Why?`,
    options: [r`Its reaction is directly coupled to the hydrolysis of one ATP`, r`Its product is consumed quickly downstream, which keeps Q small`, r`Its enzyme lowers ΔG°′ until the standard value turns negative`, r`Its product is made faster at 37 °C, which makes K_eq exceed 1`],
    correctAnswer: 1,
    explanation: r`Actual ΔG = ΔG°′ + RT ln Q, and the next enzymes remove glyceraldehyde 3-phosphate so quickly that Q stays low enough to make ΔG negative. Enzymes never change ΔG°′ or K_eq, this isomerization uses no ATP, and body temperature does not turn its equilibrium constant above 1.`,
  },
  [r`Give three structural reasons ATP hydrolysis is strongly exergonic.`]: {
    question: r`A student imagines a version of ATP in which the negative charges on the phosphate chain are fully neutralized. Based on the reasons ATP hydrolysis is exergonic, how would hydrolysis of this molecule compare?`,
    options: [r`Less exergonic, because less charge repulsion is relieved by hydrolysis`, r`More exergonic, because less charge repulsion is relieved by hydrolysis`, r`Unchanged, because repulsion only affects the rate and not the energy`, r`Unchanged, because the energy is stored in the terminal P–O bond itself`],
    correctAnswer: 0,
    explanation: r`Part of the driving force of ATP hydrolysis is relief of the electrostatic repulsion between its closely spaced negative phosphates, so removing those charges removes part of the driving force. Less relief cannot make the reaction more exergonic, the energy is not stored in one bond, and repulsion in the reactant raises its free energy, which is a thermodynamic effect.`,
  },
  [r`Phosphoryl-transfer potential ranking: {{c1::PEP}} > 1,3-BPG > {{c2::creatine phosphate}} > ATP > glucose 6-phosphate.`]: {
    question: r`Three phosphorylated compounds are hydrolyzed under standard conditions and compared with ATP (−30.5 kJ/mol). Compound A releases about twice as much free energy as ATP, compound B somewhat more than ATP, and compound C about half as much. Which assignment fits?`,
    options: [r`A is PEP, B is glucose 6-phosphate, C is creatine phosphate`, r`A is glucose 6-phosphate, B is creatine phosphate, C is PEP`, r`A is creatine phosphate, B is PEP, C is glucose 6-phosphate`, r`A is PEP, B is creatine phosphate, C is glucose 6-phosphate`],
    correctAnswer: 3,
    explanation: r`PEP (about −62 kJ/mol) has the highest phosphoryl-transfer potential, creatine phosphate (about −43) sits a little above ATP, and glucose 6-phosphate (about −14) sits below ATP. The other assignments misplace creatine phosphate above PEP or below ATP, or put the low-energy sugar phosphate at the top of the ranking.`,
  },
  [r`Why does the cell maintain NADH for catabolism but NADPH for biosynthesis?`]: {
    question: r`In a liver cell the NAD⁺/NADH ratio is about 700, while the NADP⁺/NADPH ratio is about 0.01. What do these ratios let the cell do?`,
    options: [r`NADH and NADPH both donate their electrons mainly to the electron transport chain`, r`NADP⁺ accepts electrons from fuel oxidation while NADH donates them to biosynthesis`, r`NAD⁺ donates electrons to fuel oxidation while NADPH accepts them from biosynthesis`, r`NAD⁺ accepts electrons from fuel oxidation while NADPH donates them to biosynthesis`],
    correctAnswer: 3,
    explanation: r`A mostly oxidized NAD pool is ready to accept electrons in catabolism, and a mostly reduced NADP pool is ready to donate electrons to reductive biosynthesis and antioxidant defense. The second answer assigns each job to the scarce form of the wrong pool, the third has oxidized NAD⁺ donating electrons it does not have, and NADPH is not a major fuel for the electron transport chain.`,
  },
  [r`Ubiquinone (CoQ): what kind of carrier is it, and from which sources does it collect electrons?`]: {
    question: r`A patient has a severe deficiency of coenzyme Q in the inner mitochondrial membrane. Electron flow from which sources is impaired?`,
    options: [r`From cytochrome c and Complex IV only, because CoQ acts after Complex III`, r`From Complex I, Complex II, glycerol 3-phosphate and fatty acid oxidation alike`, r`From Complex I only, because the other sources hand electrons to Complex III`, r`From Complex II only, because the other sources hand electrons to Complex III`],
    correctAnswer: 1,
    explanation: r`Coenzyme Q is the lipid-soluble mobile carrier that collects electrons from Complex I, Complex II, glycerol 3-phosphate dehydrogenase and ETF from fatty acid oxidation, and funnels all of them to Complex III. No source bypasses CoQ to reach Complex III directly, and CoQ acts before Complex III, not after it.`,
  },
  [r`Why does oligomycin stop electron transport as well as ATP synthesis in coupled mitochondria?`]: {
    question: r`Oligomycin is added to well-coupled mitochondria that are oxidizing NADH. What happens to the proton gradient and to the rate of NADH oxidation over the next minute?`,
    options: [r`The gradient collapses to zero, and NADH oxidation accelerates`, r`The gradient collapses to zero, and NADH oxidation nearly stops`, r`The gradient rises to its limit, and NADH oxidation accelerates`, r`The gradient rises to its limit, and NADH oxidation nearly stops`],
    correctAnswer: 3,
    explanation: r`With ATP synthase blocked, protons can no longer flow back into the matrix, so the gradient builds until the complexes cannot pump against it and electron transport stalls. A collapsing gradient with faster NADH oxidation describes an uncoupler, and the other two answers pair a change in the gradient with the wrong response of the chain.`,
  },
  [r`The malate-aspartate shuttle delivers cytosolic NADH electrons as matrix {{c1::NADH}}; the glycerol 3-phosphate shuttle delivers them as {{c2::FADH$_2$}}.`]: {
    question: r`Per cytosolic NADH, how many protons are pumped when its electrons enter by the malate-aspartate shuttle, and how many when they enter by the glycerol 3-phosphate shuttle? (Complexes I, III and IV pump 4, 4 and 2 protons per electron pair.)`,
    options: [r`6 by malate-aspartate; 10 by glycerol 3-phosphate`, r`10 by malate-aspartate; 10 by glycerol 3-phosphate`, r`6 by malate-aspartate; 6 by glycerol 3-phosphate`, r`10 by malate-aspartate; 6 by glycerol 3-phosphate`],
    correctAnswer: 3,
    explanation: r`The malate-aspartate shuttle delivers the electrons as matrix NADH, which uses Complexes I, III and IV (10 protons). The glycerol 3-phosphate shuttle delivers them as FADH₂ to CoQ, skipping Complex I, so only III and IV pump (6 protons). The swapped answer reverses the shuttles, and the equal answers ignore that the two shuttles enter the chain at different points.`,
  },
  [r`Anaplerotic reactions {{c1::replenish}} TCA intermediates; the quantitatively dominant one is {{c2::pyruvate carboxylase}} making oxaloacetate.`]: {
    question: r`Cultured cells are exporting large amounts of citric acid cycle intermediates for amino acid synthesis, and the cycle slows even though acetyl-CoA is plentiful. Which reaction most directly restores cycle activity?`,
    options: [r`Pyruvate carboxylase converting pyruvate to oxaloacetate`, r`Lactate dehydrogenase converting pyruvate to lactate`, r`Pyruvate dehydrogenase converting pyruvate to acetyl-CoA`, r`Citrate synthase converting oxaloacetate to citrate`],
    correctAnswer: 0,
    explanation: r`The cycle is short of four-carbon acceptor, and the main anaplerotic (replenishing) reaction is pyruvate carboxylase making oxaloacetate. Pyruvate dehydrogenase only adds more acetyl-CoA, which is already plentiful and adds no net intermediates; citrate synthase uses up oxaloacetate rather than supplying it; and lactate dehydrogenase diverts pyruvate away from the cycle.`,
  },
  [r`If acetyl-CoA enters the TCA cycle with both carbons labeled, do those labels appear in the $CO_2$ released on that same turn?`]: {
    question: r`Acetyl-CoA carrying ¹⁴C in both of its acetyl carbons enters the citric acid cycle. After exactly one turn, when oxaloacetate has been regenerated, where is the radioactivity?`,
    options: [r`None of it is in oxaloacetate, and all is in the CO₂ released`, r`All of it is in citrate, since labeled carbon cannot pass on`, r`Half of it is in oxaloacetate, and half is in the CO₂ released`, r`All of it is in oxaloacetate, and none is in the CO₂ released`],
    correctAnswer: 3,
    explanation: r`The two CO₂ molecules released in a turn come from carbons that were contributed by oxaloacetate, not from the acetyl group that just entered, so both labeled carbons are retained in the regenerated four-carbon acid. The labeled carbons are lost as CO₂ only on later turns, and isotopic labeling does not stop the cycle at citrate.`,
  },
  [r`Thiamine deficiency raises blood {{c1::pyruvate and lactate}} as PDH stalls; the resulting syndrome is {{c2::beriberi}} or Wernicke-Korsakoff.`]: {
    question: r`A malnourished patient with chronic alcohol use has confusion and an unsteady gait, and thiamine deficiency is suspected. Which pair of laboratory findings supports this?`,
    options: [r`High blood pyruvate and lactate, with low red cell transketolase activity`, r`Low blood pyruvate and lactate, with low red cell transketolase activity`, r`Low blood pyruvate and lactate, with high red cell transketolase activity`, r`High blood pyruvate and lactate, with high red cell transketolase activity`],
    correctAnswer: 0,
    explanation: r`Pyruvate dehydrogenase needs thiamine pyrophosphate, so without it pyruvate cannot enter the citric acid cycle and backs up into lactate; transketolase also needs the cofactor, so its activity falls. Low pyruvate and lactate would mean pyruvate dehydrogenase was working well, and high transketolase activity is the opposite of what a missing cofactor causes.`,
  },
  [r`Pyruvate dehydrogenase is switched off by {{c1::PDH kinase}}, which is itself stimulated by high ATP, NADH, and {{c2::acetyl-CoA}}.`]: {
    question: r`During a fast, rapid beta-oxidation fills liver mitochondria with acetyl-CoA and NADH. What is the effect on pyruvate dehydrogenase (PDH)?`,
    options: [r`PDH kinase is stimulated; PDH is phosphorylated and switched on`, r`PDH kinase is inhibited; PDH is dephosphorylated and switched on`, r`PDH kinase is inhibited; PDH is phosphorylated and switched off`, r`PDH kinase is stimulated; PDH is phosphorylated and switched off`],
    correctAnswer: 3,
    explanation: r`High acetyl-CoA, NADH and ATP stimulate PDH kinase, which phosphorylates PDH and inactivates it, sparing pyruvate when fat is supplying the acetyl-CoA. Phosphorylation switches PDH off, not on, and it is pyruvate and ADP, not the products acetyl-CoA and NADH, that inhibit the kinase.`,
  },
  [r`Electron leak at Complexes {{c1::I and III}} generates {{c2::superoxide}}, which superoxide dismutase converts to hydrogen peroxide.`]: {
    question: r`A mouse is engineered to lack mitochondrial superoxide dismutase. Which reactive species accumulates in its mitochondria, and where does it mainly originate?`,
    options: [r`Superoxide, from electrons leaking at Complexes I and III`, r`Hydrogen peroxide, from electrons leaking at Complexes II and IV`, r`Hydrogen peroxide, from electrons leaking at Complexes I and III`, r`Superoxide, from electrons leaking at Complexes II and IV`],
    correctAnswer: 0,
    explanation: r`Electrons that leak from Complexes I and III reduce O₂ by one electron to superoxide, and superoxide dismutase normally converts it to hydrogen peroxide, so without the enzyme superoxide builds up. Hydrogen peroxide is the product of the missing enzyme and would fall, and Complexes II and IV are not the main sites of leak.`,
  },
  [r`Cyanide and carbon monoxide both block cytochrome c oxidase. What does carbon monoxide do in addition?`]: {
    question: r`Two patients have blocked cytochrome c oxidase, one from cyanide and one from carbon monoxide. Which additional problem is found only in the carbon monoxide patient?`,
    options: [r`Hemoglobin iron is oxidized to the ferric state, so it can no longer bind any O₂`, r`Hemoglobin sites are occupied by the gas, and the free sites give up O₂ more easily`, r`Hemoglobin sites are occupied by the gas, and the free sites hold O₂ more tightly`, r`Complex I is blocked as well, so NADH can no longer pass electrons to coenzyme Q`],
    correctAnswer: 2,
    explanation: r`Carbon monoxide binds hemoglobin about 200 times more strongly than oxygen and raises the oxygen affinity of the remaining sites, so less oxygen is carried and less is unloaded. Easier unloading is the reverse of its effect, ferric iron describes methemoglobin, and carbon monoxide does not inhibit Complex I.`,
  },
  [r`On an oxygen-electrode trace, an uncoupler makes $O_2$ consumption {{c1::increase}} whereas an electron transport inhibitor makes it {{c2::stop}}.`]: {
    question: r`On an oxygen-electrode trace of respiring mitochondria, adding compound P makes the O₂ level fall much more steeply. Adding compound Q afterward makes the trace go flat. What are P and Q?`,
    options: [r`P is an uncoupler; Q is an electron transport inhibitor`, r`P is an uncoupler; Q is the ATP synthase inhibitor oligomycin`, r`P is oligomycin; Q is an electron transport inhibitor`, r`P is an electron transport inhibitor; Q is an uncoupler`],
    correctAnswer: 0,
    explanation: r`A steeper fall means faster O₂ consumption, which an uncoupler causes by dissipating the gradient, and a flat trace means O₂ consumption has stopped, which an electron transport inhibitor causes by blocking electron flow. Oligomycin slows respiration in coupled mitochondria rather than speeding it, and it cannot stop respiration once an uncoupler has made the gradient irrelevant.`,
  },
  [r`Escape of {{c1::cytochrome c}} from the intermembrane space into the cytosol triggers assembly of the {{c2::apoptosome}} and caspase activation.`]: {
    question: r`Cells that overexpress Bcl-2 are given a dose of DNA damage that would normally trigger intrinsic apoptosis, yet they survive. Which step fails in these cells?`,
    options: [r`Cytochrome c stays in the matrix, so caspases are activated more strongly`, r`Cytochrome c stays in the intermembrane space, so no apoptosome assembles`, r`Cytochrome c floods into the cytosol, so the apoptosome assembles too fast`, r`Coenzyme Q stays in the intermembrane space, so no apoptosome assembles`],
    correctAnswer: 1,
    explanation: r`Intrinsic apoptosis is committed when cytochrome c escapes from the intermembrane space to the cytosol, where it triggers apoptosome assembly and caspase activation; Bcl-2 blocks that release. Release into the cytosol would cause death rather than survival, coenzyme Q is a membrane lipid that is not the apoptotic signal, and cytochrome c resides in the intermembrane space, not the matrix.`,
  },
  [r`Arsenite poisons which enzyme complexes, and through what chemical interaction?`]: {
    question: r`A toxin acts by bridging pairs of neighboring thiol groups, as arsenite does. Which enzymes does it inhibit most directly, and through which cofactor?`,
    options: [r`Citrate synthase and isocitrate dehydrogenase, through lipoic acid`, r`Pyruvate and α-ketoglutarate dehydrogenases, through lipoic acid`, r`Pyruvate and α-ketoglutarate dehydrogenases, through thiamine`, r`Cytochrome c oxidase and Complex III, through their heme iron`],
    correctAnswer: 1,
    explanation: r`Reduced lipoic acid carries two adjacent thiols, which arsenite bridges, disabling the lipoate-dependent complexes: pyruvate dehydrogenase, α-ketoglutarate dehydrogenase and branched-chain keto acid dehydrogenase. Thiamine has no thiol pair, citrate synthase and isocitrate dehydrogenase do not use lipoic acid, and heme iron is the target of cyanide rather than arsenite.`,
  },
  [r`Complete oxidation of one acetyl-CoA yields about {{c1::10}} ATP, while one pyruvate yields about {{c2::12.5}}.`]: {
    question: r`A cell completely oxidizes 2 molecules of pyruvate and, separately, 2 molecules of acetyl-CoA. Using 2.5 ATP per NADH and 1.5 per FADH₂, about how many ATP does each batch yield?`,
    options: [r`30 from pyruvate; 24 from acetyl-CoA`, r`25 from pyruvate; 25 from acetyl-CoA`, r`20 from pyruvate; 25 from acetyl-CoA`, r`25 from pyruvate; 20 from acetyl-CoA`],
    correctAnswer: 3,
    explanation: r`One acetyl-CoA gives 3 NADH, 1 FADH₂ and 1 GTP (7.5 + 1.5 + 1 = 10 ATP), and pyruvate adds one more NADH at pyruvate dehydrogenase (12.5 ATP), so two of each give 20 and 25. The swapped answer reverses the two fuels, 30 and 24 use the outdated 3 and 2 ATP per carrier, and equal yields ignore the extra NADH from pyruvate dehydrogenase.`,
  },
  [r`In an oxygen-electrode run on intact mitochondria, why does adding {{c1::ADP}} sharply increase $O_2$ consumption?`]: {
    question: r`Intact, well-coupled mitochondria with plenty of succinate, phosphate and oxygen are consuming O₂ slowly. A small amount of which substance gives a sharp rise in O₂ consumption that then dies away by itself?`,
    options: [r`ADP, because ATP synthase can discharge the gradient until the ADP is used up`, r`ATP, because ATP synthase can discharge the gradient until the ATP is used up`, r`Rotenone, because Complex II then passes electrons to oxygen without limit`, r`Oligomycin, because ATP synthase then discharges the gradient without limit`],
    correctAnswer: 0,
    explanation: r`Electron transport is limited by how fast ATP synthase lets protons back in, and the synthase needs ADP; adding ADP speeds respiration until all of it has been phosphorylated, and then the rate falls back. ATP is the product and does not start the synthase, oligomycin blocks the synthase and slows respiration, and rotenone does not speed succinate oxidation.`,
  },
  [r`Contracting muscle raises matrix {{c1::$Ca^{2+}$}}, which activates two TCA dehydrogenases and {{c2::pyruvate dehydrogenase phosphatase}}.`]: {
    question: r`When a muscle fiber contracts, the matrix concentration of one ion rises and pyruvate dehydrogenase (PDH) becomes more active. Which ion is it, and how does it act on PDH?`,
    options: [r`Na⁺ inhibits PDH kinase, which leaves PDH phosphorylated and active`, r`Ca²⁺ activates PDH phosphatase, which dephosphorylates and activates PDH`, r`Na⁺ activates PDH phosphatase, which dephosphorylates and activates PDH`, r`Ca²⁺ activates PDH kinase, which phosphorylates and activates PDH`],
    correctAnswer: 1,
    explanation: r`The calcium released to trigger contraction also enters the matrix, where it activates PDH phosphatase; removing the phosphate turns PDH on (it also activates isocitrate and α-ketoglutarate dehydrogenases). Phosphorylation by PDH kinase inactivates PDH, so the kinase answers are wrong, and sodium is not the signal.`,
  },
  [r`Why does nitrite help in cyanide poisoning?`]: {
    question: r`A patient with cyanide poisoning is given nitrite, and about a fifth of the hemoglobin becomes methemoglobin. How does this help?`,
    options: [r`Methemoglobin converts cyanide into thiocyanate, which the kidneys then excrete`, r`Ferric heme in methemoglobin binds cyanide, drawing it off cytochrome c oxidase`, r`Methemoglobin passes electrons straight to O₂, bypassing cytochrome c oxidase`, r`Ferrous heme in methemoglobin binds extra O₂, raising delivery to the tissues`],
    correctAnswer: 1,
    explanation: r`Nitrite oxidizes hemoglobin iron to the ferric state, and ferric heme binds cyanide tightly, so methemoglobin competes with cytochrome c oxidase and pulls cyanide out of mitochondria. Methemoglobin cannot carry oxygen, so it does not raise delivery; conversion to thiocyanate is done by rhodanese with thiosulfate; and methemoglobin is not an electron carrier in the chain.`,
  },
  [r`Mitochondrial DNA is inherited {{c1::maternally}} and encodes {{c2::13}} subunits of the oxidative phosphorylation machinery.`]: {
    question: r`A disease is caused by a mutation in a mitochondrial gene for a subunit of Complex I. In one family the father is affected and the mother is not; in another the mother is affected and the father is not. Which children can inherit the mutation?`,
    options: [r`Only the affected father's children, sons and daughters alike`, r`The children of either affected parent, with a one-half chance`, r`Only the sons of the affected mother, and none of her daughters`, r`Only the affected mother's children, sons and daughters alike`],
    correctAnswer: 3,
    explanation: r`Mitochondrial DNA is inherited maternally, because the embryo's mitochondria come from the egg, so an affected mother can pass the mutation to all of her children of either sex and an affected father passes it to none. Sons-only transmission describes X-linked recessive patterns, and a one-half chance from either parent describes autosomal dominant inheritance.`,
  },
  [r`Complete oxidation of glucose releases about $-2870$ kJ/mol, of which roughly {{c1::one-third}} is captured as ATP.`]: {
    question: r`Complete oxidation of glucose releases about 2870 kJ/mol. A cell captures 32 ATP per glucose, each worth about 30 kJ/mol under standard conditions. About what fraction of the energy is captured, and what happens to the rest?`,
    options: [r`About one-third is captured, and the rest is released as heat`, r`About two-thirds is captured, and the rest is stored in NADH`, r`About one-third is captured, and the rest is stored in NADH`, r`About two-thirds is captured, and the rest is released as heat`],
    correctAnswer: 0,
    explanation: r`32 × 30 = 960 kJ/mol, and 960/2870 is about one-third; the remaining energy leaves as heat. Two-thirds is the share that is lost, not captured, and NADH is fully reoxidized during complete oxidation, so no energy remains stored in it.`,
  },
  [r`The NADH-to-$O_2$ span is $\Delta E^{\circ\prime} \approx 1.14$ V, giving $\Delta G^{\circ\prime} \approx -220$ kJ/mol per {{c1::two}} electrons.`]: {
    question: r`Electrons pass from succinate to O₂ across a span of ΔE°′ ≈ 0.80 V. Taking F = 96.5 kJ per volt per mole, what is ΔG°′ for the electrons delivered by one succinate?`,
    options: [r`About −154 kJ/mol`, r`About −309 kJ/mol`, r`About +154 kJ/mol`, r`About −77 kJ/mol`],
    correctAnswer: 0,
    explanation: r`One succinate, like one NADH, delivers two electrons, so ΔG°′ = −nFΔE°′ = −(2)(96.5)(0.80) ≈ −154 kJ/mol. The value −77 uses n = 1, −309 uses n = 4, and +154 drops the negative sign, which would wrongly make a positive potential difference non-spontaneous.`,
  },
  [r`About {{c1::4}} protons are spent per exported ATP: roughly 3 through ATP synthase plus 1 driving {{c2::phosphate}} import.`]: {
    question: r`In a certain species, ATP synthase needs 4 H⁺ per ATP made instead of the usual 3, and the other transport cost normally charged per exported ATP is unchanged. If 10 H⁺ are pumped per NADH, about how many ATP are exported per NADH?`,
    options: [r`About 3.3 ATP`, r`About 2.5 ATP`, r`About 2.0 ATP`, r`About 1.2 ATP`],
    correctAnswer: 2,
    explanation: r`Normally each exported ATP costs about 4 H⁺: 3 through ATP synthase plus 1 to import phosphate. Here the cost is 4 + 1 = 5 H⁺, so 10/5 = 2.0 ATP per NADH. The value 2.5 forgets the phosphate proton in this species (10/4), 3.3 ignores it in the normal case (10/3), and 1.2 uses the 6 protons of FADH₂.`,
  },
  [r`A $K^+$-carrying ionophore such as valinomycin collapses which component of the proton-motive force?`]: {
    question: r`A researcher wants to abolish the membrane potential across the inner mitochondrial membrane while leaving the pH difference in place. Which treatment does this, and why?`,
    options: [r`Dinitrophenol alone, which moves charge across without moving protons`, r`Valinomycin with K⁺, which moves protons across without moving charge`, r`Oligomycin alone, which moves protons across without moving charge`, r`Valinomycin with K⁺, which moves charge across without moving protons`],
    correctAnswer: 3,
    explanation: r`Valinomycin carries K⁺ across the membrane, neutralizing the charge separation, so it collapses only the electrical component and leaves ΔpH. Dinitrophenol is a protonophore that carries protons and collapses both components, valinomycin does not transport protons, and oligomycin blocks proton flow through ATP synthase rather than carrying anything across.`,
  },
}
